#!/usr/bin/env bash
# STAGING START — Riyadh Trust Bank (v0.6)
#
# Starts the staging API on :8001 with staging env loaded from
# .env.staging (generated by scripts/staging_setup.sh). Foreground —
# Ctrl+C stops it. Dev (port 8000) is NOT touched and can run at the
# same time.
#
# Usage:  ./scripts/staging_start.sh
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
VENV="${RTB_STAGING_VENV:-$HOME/rtb-staging-venv}"

if [ ! -f "$ROOT/.env.staging" ]; then
    echo "ERROR: $ROOT/.env.staging not found — run ./scripts/staging_setup.sh first."
    exit 1
fi
if [ ! -x "$VENV/bin/python" ]; then
    echo "ERROR: staging venv not found at $VENV — run ./scripts/staging_setup.sh first."
    exit 1
fi

# Load staging env (SECRET_KEY, DATABASE_URL, CORS_ORIGINS, ...).
# shellcheck disable=SC1091
set -a
# shellcheck source=/dev/null
. "$ROOT/.env.staging"
set +a
# Always force the staging data dir to the absolute path, even if the
# .env.staging line was edited to something relative.
export RTB_DATA_DIR="$ROOT/data-staging"
export ENVIRONMENT=staging

echo "Staging API starting on http://127.0.0.1:8001"
echo "  ENVIRONMENT=$ENVIRONMENT  RTB_DATA_DIR=$RTB_DATA_DIR"
echo "  DATABASE_URL=$DATABASE_URL"
echo "  (dev on :8000 is untouched — both can run side by side)"
cd "$ROOT/backend"
# shellcheck disable=SC1091
source "$VENV/bin/activate"
exec "$VENV/bin/python" -m uvicorn app.main:app --port 8001
